  const j = end - lo
  let a = i
  while (a > 0 && !TOKEN_STOP.has(w[a - 1]) && w.charCodeAt(a - 1) < 128) a -= 1
  let b = j
  while (b < w.length && !TOKEN_STOP.has(w[b]) && w.charCodeAt(b) < 128) b += 1
  return [w.slice(a, b), w.slice(a, i), w.slice(j, b)]
