/** A file path, not an opaque secret (see redaction.py `is_path`). */
export function isPath(v) {
  if (v.includes('+') || v.includes('//')) return false
  if (v.startsWith('/')) return true
  const segments = v.split('/').filter(Boolean)
  return v.split('/').length >= 3 && segments.every((x) => PATH_SEGMENT.test(x))
}

const isCommitId = (v) => v.length === 40 && v === v.toLowerCase()

/** Replace every match of `re` (global) through `fn(match) -> replacement`, on a fixed snapshot of `text`. */
function subWith(re, text, fn) {
  return text.replace(re, (...args) => {
    const groups = args.slice(1, -2)
    const index = args[args.length - 2]
    const m = Object.assign([args[0], ...groups], { index, input: text })
    return fn(m)
  })
}

