export function expandHome(p) {
  return p === '~' ? os.homedir() : p.startsWith('~/') ? path.join(os.homedir(), p.slice(2)) : p
}

/** (names, exact [name, value] pairs) from env files (`KEY=VALUE` or `KEY: VALUE`). Values are never logged. */
export function loadEnvFiles(paths = []) {
  const names = new Set()
  const values = []
  for (const raw of paths) {
    const file = expandHome(raw)
    let text
    try {
      text = fs.readFileSync(file, 'utf8')
    } catch {
      continue
    }
    for (const line of text.split(/\r?\n/)) {
      const m = ENV_LINE.exec(line.trim())
      if (!m) continue
      const name = m[1]
      let v = m[2].trim()
      v = v.replace(/^"+|"+$/g, '').replace(/^'+|'+$/g, '')
      names.add(name)
      if ([...v].length < 8 || !EXACT_NAME.test(name)) continue
      if (['true', 'false'].includes(v.toLowerCase()) || v.startsWith('/') || v.startsWith('http')) continue
      values.push([name, v])
    }
  }
  return [[...names], values]
}
